import { isTestFile } from './entry-points.js';
import type {
  CodeKnowledgeFile,
  CodeKnowledgeImportEdge,
  CodeKnowledgeReferenceEdge,
} from './types.js';

export function symbolKey(file: string, name: string): string {
  return `${file}�${name}`;
}

export interface ReachabilityInput {
  files: string[];
  importEdges: CodeKnowledgeImportEdge[];
  referenceEdges: CodeKnowledgeReferenceEdge[];
  entryFiles: Set<string>;
}

export interface ReachabilityResult {
  files: CodeKnowledgeFile[];
  symbolCallerCount: Map<string, number>;
}

function countCallers<T extends { from: string }>(
  edges: T[],
  keyOf: (edge: T) => string,
): Map<string, Set<string>> {
  const callers = new Map<string, Set<string>>();
  for (const edge of edges) {
    if (isTestFile(edge.from)) continue;
    const key = keyOf(edge);
    let set = callers.get(key);
    if (!set) {
      set = new Set<string>();
      callers.set(key, set);
    }
    set.add(edge.from);
  }
  return callers;
}

export function computeReachability(input: ReachabilityInput): ReachabilityResult {
  const fileCallers = countCallers(input.importEdges, (edge) => edge.to);
  const files: CodeKnowledgeFile[] = input.files.map((path) => {
    const callerCount = fileCallers.get(path)?.size ?? 0;
    const entryPoint = input.entryFiles.has(path);
    return {
      path,
      caller_count: callerCount,
      orphan: callerCount === 0 && !entryPoint,
      entry_point: entryPoint,
    };
  });

  const symbolCallers = countCallers(input.referenceEdges, (edge) =>
    symbolKey(edge.to, edge.symbol),
  );
  const symbolCallerCount = new Map<string, number>();
  for (const [key, set] of symbolCallers) {
    symbolCallerCount.set(key, set.size);
  }

  return { files, symbolCallerCount };
}
