import { createHash } from 'node:crypto';
import { readdirSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';

import { isMissingFileError, readTextIfExistsSync } from '@/core/fs/read-if-exists.js';
import { trimTrailingChar } from '@/core/text/trim-char.js';

import { getPacksForFrameworks } from '@/packs/project-packs.js';
import { hasPackage } from '@/checks/prerequisites.js';
import { selectTestRunner } from '@/checks/test-runner.js';
import type { PackageEcosystem } from '@/checks/prerequisites.js';
import type { DetectedStackProfile } from '@/core/types/introspection.js';
import type { StackPackTestRunner } from '@/core/types/pack.js';
import type { ProjectCommands, ProjectTesting } from '@/core/types/project-profile.js';

const PACKAGE_ECOSYSTEMS: Record<string, PackageEcosystem> = {
  composer: 'composer',
  php: 'composer',
  python: 'python',
  node: 'node',
  javascript: 'node',
  typescript: 'node',
  ruby: 'ruby',
};

export function resolvePackageEcosystem(
  frameworks: string[],
  projectRoot?: string,
): PackageEcosystem | null {
  for (const pack of getPacksForFrameworks(frameworks, projectRoot)) {
    const mapped = PACKAGE_ECOSYSTEMS[pack.manifest.ecosystem];
    if (mapped) return mapped;
  }
  /* v8 ignore next -- every shipped coding pack maps to a known ecosystem; the fallthrough is a guard */
  return null;
}

const ECOSYSTEM_LOCKFILES: Record<PackageEcosystem, string[]> = {
  composer: ['composer.lock'],
  python: ['poetry.lock', 'uv.lock', 'Pipfile.lock', 'pyproject.toml'],
  node: ['pnpm-lock.yaml', 'package-lock.json', 'yarn.lock', 'bun.lock'],
  ruby: ['Gemfile.lock'],
};

export function lockfileHash(
  projectRoot: string,
  ecosystem: PackageEcosystem | null,
): string | undefined {
  if (!ecosystem) return undefined;
  const files = [...ECOSYSTEM_LOCKFILES[ecosystem]];
  if (ecosystem === 'python') {
    try {
      for (const entry of readdirSync(projectRoot)) {
        if (/^requirements.*\.txt$/i.test(entry)) files.push(entry);
      }
    } catch {
      /* v8 ignore next -- unreadable project root: fall through to whatever fixed files exist */
    }
  }
  const parts: string[] = [];
  for (const file of files.sort()) {
    try {
      const text = readTextIfExistsSync(join(projectRoot, file));
      if (text !== null) parts.push(`${file}\n${text}`);
    } catch {
      /* v8 ignore next -- a present-but-unreadable lockfile contributes nothing to the hash */
    }
  }
  if (parts.length === 0) return undefined;
  return `sha256:${createHash('sha256').update(parts.join('�')).digest('hex')}`;
}

export function insertParallelFlag(
  command: string,
  flag: string,
  structuredFlags: string | undefined,
): string {
  const sf = structuredFlags?.trim();
  if (sf && command.includes(sf)) {
    return command.replace(sf, `${flag} ${sf}`);
  }
  return `${command} ${flag}`;
}

export interface TestingDerivation {
  test_parallel?: string;
  testing: ProjectTesting;
}

export function deriveTestingRecord(input: {
  runner: StackPackTestRunner;
  sequentialTest: string;
  projectRoot: string;
  ecosystem: PackageEcosystem | null;
  now: string;
  detectedBy?: 'script' | 'agent';
}): TestingDerivation {
  const { runner, sequentialTest, projectRoot, ecosystem, now } = input;
  const detected_by = input.detectedBy ?? 'script';
  const hash = lockfileHash(projectRoot, ecosystem);
  const base: Pick<ProjectTesting, 'runner_id' | 'detected_by' | 'recorded_at'> & {
    lockfile_hash?: string;
  } = {
    runner_id: runner.runner_id,
    detected_by,
    recorded_at: now,
    ...(hash ? { lockfile_hash: hash } : {}),
  };
  const parallel = runner.parallel;

  if (!parallel || parallel.mode === 'unavailable') {
    return {
      testing: {
        ...base,
        parallel: 'unavailable',
        reason: parallel?.reason ?? 'unknown',
      },
    };
  }

  if (parallel.mode === 'native') {
    return { testing: { ...base, parallel: 'native' } };
  }

  const pkg = parallel.requires_package;
  const present = pkg && ecosystem ? hasPackage(projectRoot, ecosystem, pkg) : null;
  if (present === true && parallel.flag) {
    return {
      test_parallel: insertParallelFlag(sequentialTest, parallel.flag, runner.structured_flags),
      testing: { ...base, parallel: 'available' },
    };
  }
  if (present === false) {
    return { testing: { ...base, parallel: 'unavailable', reason: `${pkg}-missing` } };
  }
  return { testing: { ...base, parallel: 'unknown', reason: 'unknown' } };
}

export function deriveTestingForProfile(input: {
  stackProfile: Pick<DetectedStackProfile, 'frameworks' | 'traits'>;
  commands: ProjectCommands;
  projectRoot?: string;
  now: string;
  detectedBy?: 'script' | 'agent';
  mirrorDoc?: boolean;
}): { commands: ProjectCommands; testing?: ProjectTesting } {
  const { stackProfile, commands, projectRoot, now } = input;
  const runner = selectTestRunner(stackProfile, commands.test, projectRoot);
  if (!runner || !projectRoot) return { commands };

  const ecosystem = resolvePackageEcosystem(stackProfile.frameworks, projectRoot);
  const derived = deriveTestingRecord({
    runner,
    sequentialTest: commands.test,
    projectRoot,
    ecosystem,
    now,
    detectedBy: input.detectedBy,
  });
  const nextCommands = derived.test_parallel
    ? { ...commands, test_parallel: derived.test_parallel }
    : commands;
  if (derived.test_parallel && input.mirrorDoc !== false) {
    upsertStackDocCommandRow(projectRoot, 'Test (parallel)', derived.test_parallel);
  }
  return { commands: nextCommands, testing: derived.testing };
}

const STACK_DOC_REL = 'docs/instructions/stack/overview.md';
const STACK_DOC_HEADER = /^\|\s*action\s*\|\s*command\s*\|$/i;

export function upsertStackDocCommandRow(
  projectRoot: string,
  action: string,
  command: string,
): void {
  const docPath = join(projectRoot, STACK_DOC_REL);

  const row = `| ${action} | ${command} |`;
  const rowRe = new RegExp(`^\\|\\s*${escapeRegExp(action)}\\s*\\|.*\\|\\s*$`, 'i');

  let content = readTextIfExistsSync(docPath) ?? '';
  const lines = content.split('\n');

  const headerIdx = lines.findIndex((line) => STACK_DOC_HEADER.test(line.trim()));
  if (headerIdx === -1) {
    const section = [
      '',
      '## Test runner (recorded by paqad)',
      '',
      '| Action | Command |',
      '|--------|---------|',
      row,
      '',
    ].join('\n');
    content = content.length > 0 ? `${trimTrailingChar(content, '\n')}\n${section}` : section;
    writeStackDoc(docPath, `${trimTrailingChar(content, '\n')}\n`);
    return;
  }

  const existingIdx = lines.findIndex(
    (line, idx) => idx > headerIdx + 1 && rowRe.test(line.trim()),
  );
  if (existingIdx !== -1) {
    lines[existingIdx] = row;
  } else {
    let end = headerIdx + 1;
    while (end + 1 < lines.length && lines[end + 1]!.trim().startsWith('|')) end += 1;
    lines.splice(end + 1, 0, row);
  }
  writeStackDoc(docPath, lines.join('\n'));
}

function writeStackDoc(docPath: string, content: string): void {
  try {
    writeFileSync(docPath, content);
  } catch (error) {
    if (!isMissingFileError(error)) throw error;
  }
}

function escapeRegExp(text: string): string {
  return text.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}
